/**
 * @brief Distribution point name: either a full GeneralNames set or a relative name.
 */
typedef struct DIST_POINT_NAME_st {
    /** Discriminant selecting @c fullname (0) or @c relativename (1). */
    int type;
    /**
     * @brief Union of distribution point name forms; the active arm matches @c type.
     */
    union {
        /** Full distribution point name as a set of GeneralNames. */
        GENERAL_NAMES *fullname;
        /** Name relative to the CRL issuer, as a sequence of Name entries. */
        STACK_OF(X509_NAME_ENTRY) *relativename;
    } name;
    /* If relativename then this contains the full distribution point name */
    /** Issuer name used to expand a relative distribution point name. */
    X509_NAME *dpname;
} DIST_POINT_NAME;
