/**
 * @brief Return the authorityCertSerialNumber from the Authority Key Identifier extension.
 * @param x Certificate to query.
 * @return Internal pointer to the serial number, or NULL if absent or unparsable; do not free.
 */
const ASN1_INTEGER *X509_get0_authority_serial(X509 *x);

/**
 * @brief Return how many entries are in the X509_PURPOSE table.
 * @return Number of registered purpose definitions.
 */
int X509_PURPOSE_get_count(void);
/**
 * @brief Return the purpose table entry at a numeric index.
 * @param idx Index in [0, X509_PURPOSE_get_count()).
 * @return Pointer to the X509_PURPOSE entry, or NULL if @p idx is out of range.
 */
X509_PURPOSE *X509_PURPOSE_get0(int idx);
/**
 * @brief Look up a purpose table index by short name.
 * @param sname Short purpose name such as "sslserver" or "smimesign".
 * @return Index suitable for X509_PURPOSE_get0, or -1 if not found.
 */
int X509_PURPOSE_get_by_sname(const char *sname);
/**
 * @brief Look up a purpose table index by purpose identifier.
 * @param id Purpose id such as X509_PURPOSE_SSL_CLIENT.
 * @return Index suitable for X509_PURPOSE_get0, or -1 if not found.
 */
int X509_PURPOSE_get_by_id(int id);
/**
 * @brief Register or replace a certificate purpose entry in the purpose table.
 * @param id Purpose identifier to add or update.
 * @param trust Default trust id associated with this purpose.
 * @param flags Purpose flags; X509_PURPOSE_DYNAMIC is managed internally.
 * @param ck Callback that decides whether a certificate meets this purpose.
 * @param name Long human-readable purpose name (copied).
 * @param sname Short purpose name used by X509_PURPOSE_get_by_sname (copied).
 * @param arg Application data stored in the purpose entry's usr_data field.
 * @return 1 on success, or 0 on failure.
 */
int X509_PURPOSE_add(int id, int trust, int flags,
    int (*ck)(const X509_PURPOSE *, const X509 *, int),
    const char *name, const char *sname, void *arg);
/**
 * @brief Return the long human-readable name of a purpose table entry.
 * @param xp Purpose entry to query.
 * @return Internal name string; do not free.
 */
char *X509_PURPOSE_get0_name(const X509_PURPOSE *xp);
/**
 * @brief Return the short name of a purpose table entry.
 * @param xp Purpose entry to query.
 * @return Internal short-name string; do not free.
 */
char *X509_PURPOSE_get0_sname(const X509_PURPOSE *xp);
/**
 * @brief Return the default trust identifier associated with a purpose entry.
 * @param xp Purpose entry to query.
 * @return Trust id stored in the entry.
 */
int X509_PURPOSE_get_trust(const X509_PURPOSE *xp);
/**
 * @brief Free all dynamically registered purpose table entries.
 */
void X509_PURPOSE_cleanup(void);
/**
 * @brief Return the purpose identifier from a purpose table entry.
 * @param xp Purpose entry to query.
 * @return Purpose id such as X509_PURPOSE_SSL_SERVER.
 */
int X509_PURPOSE_get_id(const X509_PURPOSE *xp);

/**
 * @brief Collect email addresses from a certificate's subject and subjectAltName.
 * @param x Certificate to query.
 * @return Newly allocated stack of email strings, or NULL on failure; free with X509_email_free.
 */
STACK_OF(OPENSSL_STRING) *X509_get1_email(X509 *x);
/**
 * @brief Collect email addresses from a certificate request's subject and subjectAltName.
 * @param x Certificate request to query.
 * @return Newly allocated stack of email strings, or NULL on failure; free with X509_email_free.
 */
STACK_OF(OPENSSL_STRING) *X509_REQ_get1_email(X509_REQ *x);
/**
 * @brief Free a stack of email strings returned by X509_get1_email or X509_REQ_get1_email.
 * @param sk Stack to free, or NULL.
 */
void X509_email_free(STACK_OF(OPENSSL_STRING) *sk);
/**
 * @brief Extract OCSP responder URIs from a certificate's Authority Information Access extension.
 * @param x Certificate to examine.
 * @return New stack of OCSP URI strings (free with X509_email_free()), or NULL if none or on error.
 */
STACK_OF(OPENSSL_STRING) *X509_get1_ocsp(X509 *x);
/* Flags for X509_check_* functions */

/*
 * Always check subject name for host match even if subject alt names present
 */
#define X509_CHECK_FLAG_ALWAYS_CHECK_SUBJECT 0x1
/* Disable wildcard matching for dnsName fields and common name. */
#define X509_CHECK_FLAG_NO_WILDCARDS 0x2
/* Wildcards must not match a partial label. */
#define X509_CHECK_FLAG_NO_PARTIAL_WILDCARDS 0x4
/* Allow (non-partial) wildcards to match multiple labels. */
#define X509_CHECK_FLAG_MULTI_LABEL_WILDCARDS 0x8
/* Constraint verifier subdomain patterns to match a single labels. */
#define X509_CHECK_FLAG_SINGLE_LABEL_SUBDOMAINS 0x10
/* Never check the subject CN */
#define X509_CHECK_FLAG_NEVER_CHECK_SUBJECT 0x20
/*
 * Match reference identifiers starting with "." to any sub-domain.
 * This is a non-public flag, turned on implicitly when the subject
 * reference identity is a DNS name.
 */
#define _X509_CHECK_FLAG_DOT_SUBDOMAINS 0x8000

/**
 * @brief Check whether a certificate matches a DNS host name.
 * @param x Certificate whose subjectAltName / subject CN are examined.
 * @param chk Host name bytes (not necessarily NUL-terminated when @p chklen is set).
 * @param chklen Length of @p chk, or 0 to use strlen(@p chk).
 * @param flags X509_CHECK_FLAG_* controlling matching behaviour.
 * @param peername Optional output for a newly allocated matched name string, or NULL.
 * @return 1 on match, 0 on no match, or -1 on malformed input / error.
 */
int X509_check_host(X509 *x, const char *chk, size_t chklen,
    unsigned int flags, char **peername);
/**
 * @brief Check whether a certificate's subjectAltName/subject email matches @p chk.
 * @param x Certificate to check.
 * @param chk Email address to compare (need not be NUL-terminated if @p chklen is set).
 * @param chklen Length of @p chk in bytes, or 0 to use strlen(@p chk).
 * @param flags X509_CHECK_FLAG_* controlling comparison behavior.
 * @return 1 on match, 0 on no match, or -1 on malformed input / error.
 */
int X509_check_email(X509 *x, const char *chk, size_t chklen,
    unsigned int flags);
/**
 * @brief Check whether a certificate's subjectAltName contains an IP address in binary form.
 * @param x Certificate to match.
 * @param chk IPv4 (4 bytes) or IPv6 (16 bytes) address in network byte order.
 * @param chklen Length of @p chk in bytes (4 or 16).
 * @param flags X509_CHECK_FLAG_* controlling comparison behaviour (currently unused for IP).
 * @return 1 on match, 0 on no match, or -1 on malformed input / error.
 */
int X509_check_ip(X509 *x, const unsigned char *chk, size_t chklen,
    unsigned int flags);
/**
 * @brief Check whether a certificate's subjectAltName contains an IP address given as text.
 * @param x Certificate to check.
 * @param ipasc ASCII IPv4 or IPv6 address.
 * @param flags X509_CHECK_FLAG_* controlling matching behaviour.
 * @return 1 on match, 0 on no match, or -1 on malformed input / error.
 */
int X509_check_ip_asc(X509 *x, const char *ipasc, unsigned int flags);

/**
 * @brief Convert an ASCII IPv4 or IPv6 address to an OCTET STRING for GeneralName iPAddress.
 * @param ipasc Address text such as "192.0.2.1" or "2001:db8::1".
 * @return Newly allocated ASN1_OCTET_STRING with the binary address, or NULL on failure.
 */
ASN1_OCTET_STRING *a2i_IPADDRESS(const char *ipasc);
/**
 * @brief Convert an ASCII IP address or CIDR prefix to an OCTET STRING for name constraints.
 * @param ipasc Address or prefix text (for example "192.0.2.0/24" or "2001:db8::/32").
 * @return Newly allocated ASN1_OCTET_STRING, or NULL on failure.
 */
ASN1_OCTET_STRING *a2i_IPADDRESS_NC(const char *ipasc);
/**
 * @brief Populate an X509_NAME from a stack of configuration DN name/value pairs.
 * @param nm Name object to receive Relative Distinguished Name attributes.
 * @param dn_sk Stack of CONF_VALUE entries describing DN components (multi-valued RDNs via '+').
 * @param chtype Multibyte string type for attribute values (for example MBSTRING_ASC).
 * @return 1 on success, or 0 on failure.
 */
int X509V3_NAME_from_section(X509_NAME *nm, STACK_OF(CONF_VALUE) *dn_sk,
    unsigned long chtype);

/**
 * @brief Print a certificate policy tree node (OID, criticality, qualifiers) to a BIO.
 * @param out BIO that receives the formatted policy node.
 * @param node Policy node to print.
 * @param indent Indentation width in spaces.
 */
void X509_POLICY_NODE_print(BIO *out, X509_POLICY_NODE *node, int indent);
