/**
 * @brief RFC 3779 choice between inheriting AS identifiers and listing them explicitly.
 */
typedef struct ASIdentifierChoice_st {
    /** Discriminator: ASIdentifierChoice_inherit or ASIdentifierChoice_asIdsOrRanges. */
    int type;
    /**
     * @brief Choice payload selected by @c type.
     */
    union {
        /** Inherit AS identifiers from the issuer when @c type is ASIdentifierChoice_inherit. */
        ASN1_NULL *inherit;
        /** Explicit AS numbers or ranges when @c type is ASIdentifierChoice_asIdsOrRanges. */
        ASIdOrRanges *asIdsOrRanges;
    } u;
} ASIdentifierChoice;

