/*
 * API tag for elements of the ASIdentifer SEQUENCE.
 */
#define V3_ASID_ASNUM 0
#define V3_ASID_RDI 1

/*
 * AFI values, assigned by IANA.  It'd be nice to make the AFI
 * handling code totally generic, but there are too many little things
 * that would need to be defined for other address families for it to
 * be worth the trouble.
 */
#define IANA_AFI_IPV4 1
#define IANA_AFI_IPV6 2

/*
 * Utilities to construct and extract values from RFC3779 extensions,
 * since some of the encodings (particularly for IP address prefixes
 * and ranges) are a bit tedious to work with directly.
 */
/**
 * @brief Mark an ASIdentifiers choice as inheriting from the issuer.
 * @param asid Extension value to modify.
 * @param which V3_ASID_ASNUM or V3_ASID_RDI selecting which choice inherits.
 * @return 1 on success, or 0 on failure.
 */
int X509v3_asid_add_inherit(ASIdentifiers *asid, int which);
/**
 * @brief Add a single AS number or an inclusive AS number range to an ASIdentifiers value.
 * @param asid Extension value to modify.
 * @param which V3_ASID_ASNUM or V3_ASID_RDI selecting which choice to update.
 * @param min Lowest AS number (also the sole ID when @p max is NULL).
 * @param max Highest AS number for a range, or NULL to add @p min as a single ID.
 * @return 1 on success, or 0 on failure.
 */
int X509v3_asid_add_id_or_range(ASIdentifiers *asid, int which,
    ASN1_INTEGER *min, ASN1_INTEGER *max);
/**
 * @brief Mark an address family in an IPAddrBlocks value as inheriting from the issuer.
 * @param addr Extension value to modify.
 * @param afi Address Family Identifier (IANA AFI).
 * @param safi Optional Subsequent Address Family Identifier, or NULL.
 * @return 1 on success, or 0 on failure.
 */
int X509v3_addr_add_inherit(IPAddrBlocks *addr,
    const unsigned afi, const unsigned *safi);
/**
 * @brief Add an IP address prefix to an IPAddrBlocks (RFC 3779) extension value.
 * @param addr Extension value to modify.
 * @param afi Address Family Identifier (IANA AFI).
 * @param safi Optional Subsequent Address Family Identifier, or NULL.
 * @param a Address bytes in network byte order (length implied by @p afi).
 * @param prefixlen Prefix length in bits.
 * @return 1 on success, or 0 on failure.
 */
int X509v3_addr_add_prefix(IPAddrBlocks *addr,
    const unsigned afi, const unsigned *safi,
    unsigned char *a, const int prefixlen);
/**
 * @brief Add an inclusive IP address range to an IPAddrBlocks value.
 * @param addr Extension value to modify.
 * @param afi Address Family Identifier (IANA AFI).
 * @param safi Optional Subsequent Address Family Identifier, or NULL.
 * @param min Lowest address in network byte order (length implied by @p afi).
 * @param max Highest address in network byte order (same length as @p min).
 * @return 1 on success, or 0 on failure.
 */
int X509v3_addr_add_range(IPAddrBlocks *addr,
    const unsigned afi, const unsigned *safi,
    unsigned char *min, unsigned char *max);
/**
 * @brief Return the Address Family Identifier from an IPAddressFamily entry.
 * @param f Address-family entry whose @c addressFamily OCTET STRING is read.
 * @return 16-bit AFI (for example IANA_AFI_IPV4 or IANA_AFI_IPV6), or 0 if unavailable.
 */
unsigned X509v3_addr_get_afi(const IPAddressFamily *f);
/**
 * @brief Expand an IPAddressOrRange into inclusive @p min/@p max address bytes for @p afi.
 * @param aor Address or range choice to expand.
 * @param afi Address family (IANA_AFI_IPV4 or IANA_AFI_IPV6).
 * @param min Output buffer receiving the low address bytes.
 * @param max Output buffer receiving the high address bytes.
 * @param length Capacity of @p min and @p max in bytes (4 for IPv4, 16 for IPv6).
 * @return Address length written on success, or 0 on failure.
 */
int X509v3_addr_get_range(IPAddressOrRange *aor, const unsigned afi,
    unsigned char *min, unsigned char *max,
    const int length);

/*
 * Canonical forms.
 */
/**
 * @brief Test whether an ASIdentifiers value is already in RFC 3779 canonical form.
 * @param asid Extension value to check, or NULL (treated as canonical).
 * @return 1 if canonical (or @p asid is NULL), or 0 otherwise.
 */
int X509v3_asid_is_canonical(ASIdentifiers *asid);
/**
 * @brief Test whether an IPAddrBlocks value is already in RFC 3779 canonical form.
 * @param addr Extension value to check, or NULL (treated as canonical).
 * @return 1 if canonical (or @p addr is NULL), or 0 otherwise.
 */
int X509v3_addr_is_canonical(IPAddrBlocks *addr);
/**
 * @brief Sort and merge an ASIdentifiers value into RFC 3779 canonical form.
 * @param asid Extension value to rewrite in place.
 * @return 1 on success, or 0 on failure.
 */
int X509v3_asid_canonize(ASIdentifiers *asid);
/**
 * @brief Sort and merge an IPAddrBlocks value into RFC 3779 canonical form.
 * @param addr Extension value to rewrite in place.
 * @return 1 on success, or 0 on failure.
 */
int X509v3_addr_canonize(IPAddrBlocks *addr);

/*
 * Tests for inheritance and containment.
 */
/**
 * @brief Test whether an ASIdentifiers value uses inheritance for ASNUM or RDI.
 * @param asid Extension value to inspect.
 * @return 1 if either choice is inherit, or 0 otherwise.
 */
int X509v3_asid_inherits(ASIdentifiers *asid);
/**
 * @brief Report whether an IPAddrBlocks value uses inheritance from the issuer.
 * @param addr IP address blocks extension to query.
 * @return 1 if any family inherits, or 0 otherwise.
 */
int X509v3_addr_inherits(IPAddrBlocks *addr);
/**
 * @brief Test whether AS identifier set @p a is covered by set @p b.
 * @param a Candidate subset (NULL is treated as a subset of any @p b).
 * @param b Candidate superset.
 * @return 1 if @p a is a subset of @p b (neither may use inheritance), or 0 otherwise.
 */
int X509v3_asid_subset(ASIdentifiers *a, ASIdentifiers *b);
/**
 * @brief Test whether IP address block set @p a is covered by set @p b.
 * @param a Candidate subset (NULL is treated as a subset of any @p b).
 * @param b Candidate superset.
 * @return 1 if @p a is a subset of @p b (neither may use inheritance), or 0 otherwise.
 */
int X509v3_addr_subset(IPAddrBlocks *a, IPAddrBlocks *b);

/*
 * Check whether RFC 3779 extensions nest properly in chains.
 */
/**
 * @brief Validate RFC 3779 AS identifier nesting along a certificate chain in a store context.
 * @param ctx Store context whose verified chain and verify callback are used.
 * @return 1 if the path is valid, or 0 on failure (errors reported via @p ctx).
 */
int X509v3_asid_validate_path(X509_STORE_CTX *ctx);
/**
 * @brief Validate RFC 3779 IP address blocks along the certification path in @p ctx.
 * @param ctx Store context whose chain is checked for consistent IPAddrBlocks inheritance.
 * @return 1 if valid, or 0 on failure (sets verify error on @p ctx).
 */
int X509v3_addr_validate_path(X509_STORE_CTX *ctx);
/**
 * @brief Validate that AS identifiers in @p ext are covered by ancestors in @p chain.
 * @param chain Certificate chain (leaf first) used to check nested ASIdentifiers extensions.
 * @param ext AS resource set claimed by the leaf (or NULL to treat as empty).
 * @param allow_inheritance Non-zero to permit inherit elements when validating.
 * @return 1 if @p ext is valid given @p chain, or 0 otherwise.
 */
int X509v3_asid_validate_resource_set(STACK_OF(X509) *chain,
    ASIdentifiers *ext,
    int allow_inheritance);
/**
 * @brief Validate that IP address blocks in @p ext are covered by ancestors in @p chain.
 * @param chain Certificate chain (leaf first) used to check nested IPAddrBlocks extensions.
 * @param ext IP address resource set claimed by the leaf (or NULL to treat as empty).
 * @param allow_inheritance Non-zero to permit inherit elements when validating.
 * @return 1 if @p ext is valid given @p chain, or 0 otherwise.
 */
int X509v3_addr_validate_resource_set(STACK_OF(X509) *chain,
    IPAddrBlocks *ext, int allow_inheritance);

#endif /* OPENSSL_NO_RFC3779 */

